/// The opener of the local trim valve's marker (issue #171/#195): the
/// in-memory valve prepends this note when it drops older messages
/// without a summarizer (see `AutoCompactor._localTrimFallback`).
const localTrimMarkerPrefix = '[context trimmed locally:';

/// The pointer of a FOLD (GOAL #2394 D5/AC9): `[expand 3-140]` — one
/// line, engine-generated, sitting where the folded range's first record
/// rendered. Never tagged (the record alias rides the transfer record at
/// its own position — a tag here would name the same seq twice).
String expandMarker({required int from, int? to}) =>
    to == null || to == from ? '[expand $from]' : '[expand $from-$to]';

/// The consolidated HIDE marker of one pair/range (GOAL #2394 D5/AC9):
/// `<label> [expand 142-143]` at the carrier's position — ONE line for
/// the whole range instead of a marker per record (`labels` rides the
/// `HiddenRangeRecord`; a failed label leaves the bare pointer).
String consolidatedHideMarker({required int from, int? to, String? label}) {
  final pointer = expandMarker(from: from, to: to);
  final text = label?.trim() ?? '';
  return text.isEmpty ? pointer : '$text $pointer';
}

final RegExp _markerTextPattern = RegExp(r'^\[\d+(?:-\d+)?:(?:hidden|ckpt)·');

/// GOAL #2394: the wire prefix of a marker that projects from a record —
/// the record tag (`m142 `) the tag epoch puts on the first text block.
final RegExp _recordTagPrefix = RegExp(r'^m\d+ ');

/// The fold/consolidated pointer closing a marker text (D12): the only
/// new marker form, always engine-generated and always the WHOLE text
/// behind an optional label — `[expand 3-140]`, `old session list
/// [expand 142-143]`. End-anchored alone it would also match genuine
/// content that merely ends in a quoted pointer (docs and skill texts
/// quote `[expand 3-140]`), and three boundary detectors key off this
/// predicate (review round 1) — so the text before the pointer must be
/// a label the ENGINE could have written: one line, no brackets, at most
/// the hide-label budget (`hideLabelMaxChars` / `hideLabelMaxWords` in
/// hand_over.dart, mirrored here).
final RegExp _expandPointerPattern = RegExp(r'\[expand \d+(?:-\d+)?\]\s*$');

/// The label budget an ENGINE-written marker may carry before its
/// pointer (gh-2492 C4/C5): the collapsed ledger markers and the hide
/// histogram labels (`bash ×61 · read ×40 · 12:41–13:44`) are wider than
/// the judge's hide labels — the head the marker predicate accepts grows
/// to cover every ENGINE shape. Model-written labels stay at the tight
/// `sanitizeHideLabel` budget (48 chars / 6 words); a sanitizer output
/// always fits this predicate (a subset), so tool-pairing repair and the
/// operative-pin detector keep resolving every label the engine renders.
const int _markerLabelMaxChars = 96;
const int _markerLabelMaxWords = 20;

bool _isEngineExpandPointer(String body) {
  final match = _expandPointerPattern.firstMatch(body);
  if (match == null) return false;
  // The engine writes a marker as ONE line: a pointer that only ends a
  // longer text (a quoted pointer on the last line of a tool result) is
  // not a marker.
  final head = body.substring(0, match.start);
  if (head.contains('\n')) return false;
  final label = head.trim();
  if (label.isEmpty) return true;
  if (label.contains('[') || label.contains(']')) return false;
  return label.length <= _markerLabelMaxChars &&
      label.split(RegExp(r'\s+')).length <= _markerLabelMaxWords;
}

/// Tool-pairing repair, the operative-pin detector and the image registry
/// (issue #195 F2: hidden history may have carried images whose
/// first-seen indexes the surviving citations still name) all key off
/// this — the new forms must resolve exactly like the old ones (REG-12).
